function pa = startMaskingNoise(noiseCfg)
%pa = startMaskingNoise(noiseCfg)
%
% Start looped masking noise on the default audio device (Psychtoolbox
% PsychPortAudio, its own playback thread). With noiseCfg.file set, that sound file
% is looped at its own sample rate (rrst.loadMaskingSound); otherwise the buffer is
% generated by rrst.maskingNoise. Both loop without a click. Replaces playSound.m,
% which loaded a 60-minute wav file (several GB as doubles) and hard-coded audio
% device 4.

InitializePsychSound(1);
if isfield(noiseCfg, 'file') && strlength(string(noiseCfg.file)) > 0
    [x, fs] = rrst.loadMaskingSound(noiseCfg.file);
    x = noiseCfg.volume * x;
    [~, name, ext] = fileparts(noiseCfg.file);
    what = string(name) + ext;
else
    fs = noiseCfg.fs;
    x = noiseCfg.volume * rrst.maskingNoise(fs, noiseCfg.durS, noiseCfg.colour, 1);
    x = [x x];
    what = string(noiseCfg.colour);
end
pa = PsychPortAudio('Open', [], 1, 1, fs, 2);
PsychPortAudio('FillBuffer', pa, x');
PsychPortAudio('Start', pa, 0, 0, 1);      % 0 repetitions = loop until stopped
fprintf('Masking noise: %s, volume %g, %.0f s loop at %g Hz.\n', what, noiseCfg.volume, ...
    size(x, 1) / fs, fs);
end
